// Recibe el anuncio (webhook) y extrae precio, m², zona y URL desde
// campos estructurados o desde el texto libre. Conserva la config.
function parseNum(v) {
  if (v == null) return null;
  if (typeof v === 'number') return v;
  let s = String(v).trim().replace(/[.  \s]/g, '').replace(',', '.');
  if (s === '') return null;
  const n = Number(s);
  return isNaN(n) ? null : n;
}
const items = $input.all();
const salida = [];
for (const item of items) {
  const cuerpo = item.json && item.json.body;
  const lista = Array.isArray(cuerpo) ? cuerpo
    : [cuerpo && typeof cuerpo === 'object' ? cuerpo : item.json];
  for (const a of lista) {
    const nombre = a.titulo || a.title || a.nombre || '';
    const texto = a.texto || a.text || a.descripcion || a.description || '';
    let zona = a.zona || a.zone || a.ubicacion || null;
    const url = a.url || a.link || a.enlace || (typeof a.href === 'string' ? a.href : null);
    let precio = a.precio != null ? parseNum(a.precio) : null;
    let m2 = a.m2 != null ? parseNum(a.m2) : null;
    const campo = nombre + ' ' + texto;
    const t = ' ' + campo.toLowerCase() + ' ';
    if (precio == null) {
      const mP = t.match(/(\d{1,3}(?:[.,\s]\d{3})+|\d+)\s*(?:euros?|eur|\€)/i);
      if (mP) precio = parseNum(mP[1]);
      else { const mK = t.match(/(\d{2,3})\s*k\b/); if (mK) precio = parseNum(mK[1]) * 1000; }
    }
    if (m2 == null) {
      const mM = t.match(/(\d{2,4})\s*(?:m2|m²|mts|metros?)\b/);
      if (mM) m2 = parseNum(mM[1]);
    }
    if (!zona) {
      for (const z of ['jerez centro', 'casco antiguo', 'santiago', 'san miguel', 'la granja', 'el puerto']) {
        if (t.includes(z)) { zona = z[0].toUpperCase() + z.slice(1); break; }
      }
      if (!zona && t.includes('jerez')) zona = 'Jerez de la Frontera';
    }
    salida.push({ json: Object.assign({}, item.json, {
      titulo: nombre, texto: texto, precio: precio, m2: m2, zona: zona, url: url
    }) });
  }
}
return salida;

// Aplica el perfil de inversión de Jerez y construye el mensaje HTML.
function fmt(v) { return v == null ? '—' : Math.round(v).toLocaleString('es-ES'); }
const RED_FLAGS = ['ocupado','ocupada','okupa','sin posesion','sin posesión','subasta',
  'no visitable','no se puede visitar','sin cedula','sin cédula',
  'problemas de cedula','problemas de cédula'];
const items = $input.all();
const salida = [];
for (const item of items) {
  const p = item.json;
  const texto = ((p.texto || '') + ' ' + (p.titulo || '')).toLowerCase();
  const banderas = RED_FLAGS.filter(f => texto.includes(f));
  const zonaObj = p.zonaObjetivo || 'Jerez de la Frontera';
  const minPrecio = Number(p.minPrecio) || 75000;
  const maxPrecio = Number(p.maxPrecio) || 120000;
  const maxEurM2 = Number(p.maxEurM2) || 1600;
  const rentEurM2Mes = Number(p.rentEurM2Mes) || 9;
  const minRent = Number(p.minRentabilidad) || 7;
  const soloLH = p.soloLlamarHoy === true || String(p.soloLlamarHoy) === 'true';
  const precio = p.precio, m2 = p.m2, zona = p.zona || zonaObj;
  if (banderas.length) {
    salida.push({ json: { ...p, veredicto: 'DESCARTAR',
      motivo: '🚩 Riesgo: ' + banderas.join(', '), mensaje: null } });
    continue;
  }
  if (precio == null || m2 == null || m2 <= 0) {
    salida.push({ json: { ...p, veredicto: 'REVISAR',
      motivo: '⚠️ Datos incompletos (falta precio o m²)', mensaje: null } });
    continue;
  }
  const eurM2 = precio / m2;
  const rentabilidad = (rentEurM2Mes * m2 * 12 / precio) * 100;
  const descuento = (1 - eurM2 / maxEurM2) * 100;
  const enRango = precio >= minPrecio && precio <= maxPrecio;
  const cumpleTope = eurM2 <= maxEurM2;
  const cumpleRent = rentabilidad >= minRent;
  const veredicto = (enRango && cumpleTope && cumpleRent) ? 'LLAMAR HOY' : 'REVISAR';
  if (soloLH && veredicto !== 'LLAMAR HOY') {
    salida.push({ json: { ...p, veredicto, mensaje: null,
      motivo: 'No cumple perfil: fuera de rango/tope €/m² o rentabilidad' } });
    continue;
  }
  const mapsLink = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(zona || zonaObj);
  const etiqueta = veredicto === 'LLAMAR HOY'
    ? '🏠 <b>OPORTUNIDAD · LLAMAR HOY</b>' : '👀 <b>REVISAR</b>';
  let msg = [
    etiqueta,
    '📋 ' + (p.titulo || 'Sin título'),
    '📍 <b>' + (zona || zonaObj) + '</b>',
    '💶 ' + fmt(precio) + ' € · ' + fmt(m2) + ' m² · ' + fmt(eurM2) + ' €/m²',
    '📈 Rentabilidad bruta: <b>' + rentabilidad.toFixed(1) + '%</b>',
    '🎯 Descuento frente a ' + fmt(maxEurM2) + ' €/m²: ' + descuento.toFixed(0) + '%',
    '🧭 <a href="' + mapsLink + '">Ver ubicación en Google Maps</a>'
  ].join('\n');
  if (p.url) msg += '\n🔗 <a href="' + p.url + '">Ver anuncio original</a>';
  salida.push({ json: { ...p,
    eurM2: Math.round(eurM2 * 100) / 100,
    rentabilidad: Math.round(rentabilidad * 100) / 100,
    descuento: Math.round(descuento * 100) / 100,
    veredicto: veredicto, mensaje: msg, mapsLink: mapsLink } });
}
return salida;

// Deduplicación persistente por URL (o precio+m²+zona) con ventana dedupDias.
const items = $input.all();
if (!items.length) return [];
const dias = Number(items[0].json.dedupDias) || 365;
const ahora = Date.now();
const tope = ahora - dias * 86400 * 1000;
const st = $getWorkflowStaticData('global');
if (!st.vistos) st.vistos = {};
const salida = [];
for (const item of items) {
  const p = item.json;
  if (!p.mensaje) continue;
  const clave = p.url || ('precio=' + (p.precio || '') + '&m2=' + (p.m2 || '') + '&zona=' + (p.zona || ''));
  const ultima = st.vistos[clave] || 0;
  if (!ultima || ultima < tope) salida.push(item);
  st.vistos[clave] = ahora;
}
if (Object.keys(st.vistos).length > 5000) {
  for (const k of Object.keys(st.vistos)) { if (st.vistos[k] < tope) delete st.vistos[k]; }
}
return salida;

// Genera un ítem por cada destinatario de Telegram (persona o grupo).
const items = $input.all();
const salida = [];
for (const item of items) {
  const p = item.json;
  if (!p.mensaje) continue;
  const chats = String(p.telegramChats || '').split(/[,\s;]+/).filter(Boolean);
  for (const chatId of chats) {
    salida.push({ json: { ...p, chatId: chatId.trim(), mensaje: p.mensaje } });
  }
}
return salida;
